var documenterSearchIndex = {"docs":
[{"location":"guide/#User-Guide","page":"User Guide","title":"User Guide","text":"This guide is automatically generated from the comprehensive USER_GUIDE.md.\n\nFor the most up-to-date information, see USER_GUIDE.md in the repository.\n\n\n\nPages = [\"guide.md\"]\nDepth = 3\n\n","category":"section"},{"location":"guide/#Quick-Start","page":"User Guide","title":"Quick Start","text":"using MissingDataViz\nusing DataFrames\n\n# Create sample data with missing values\ndf = DataFrame(\n    Name = [\"Alice\", \"Bob\", missing, \"David\", \"Eve\"],\n    Age = [25, missing, 30, missing, 35],\n    Salary = [50000, 60000, missing, 70000, missing],\n    Department = [\"HR\", \"IT\", \"IT\", missing, \"HR\"]\n)\n\n# One-line complete analysis\nresults = diagnose_missing(df)\n# → Displays 4 plots automatically\n# → Returns statistics and figures\n\n","category":"section"},{"location":"guide/#Core-Functions","page":"User Guide","title":"Core Functions","text":"","category":"section"},{"location":"guide/#Pattern-Detection","page":"User Guide","title":"Pattern Detection","text":"# Get missing data pattern matrix (boolean)\npattern = missing_pattern(df)\n\n# Get percentage of missing values per column\npercentages = missing_percentage(df)\n\n# Get count of missing values per column\ncounts = missing_count(df)","category":"section"},{"location":"guide/#Visualizations","page":"User Guide","title":"Visualizations","text":"# Missing data matrix heatmap\nfig1 = plot_missing_matrix(df)\n\n# Bar chart of missing percentages\nfig2 = plot_missing_bars(df)\n\n# Correlation matrix of missingness\nfig3 = plot_missing_correlation(df)\n\n# Combined overview dashboard\nfig4 = plot_missing_overview(df)","category":"section"},{"location":"guide/#All-in-One-Analysis","page":"User Guide","title":"All-in-One Analysis","text":"# Interactive mode (default)\nresults = diagnose_missing(df)\n\n# Batch mode (generate HTML report)\nresults = diagnose_missing(df, report=true, output=\"report.html\")\n\n","category":"section"},{"location":"guide/#Workflows","page":"User Guide","title":"Workflows","text":"","category":"section"},{"location":"guide/#Interactive-Analysis","page":"User Guide","title":"Interactive Analysis","text":"using MissingDataViz, DataFrames\n\ndf = # your data loading\n\n# Automatic analysis with plot display\nresults = diagnose_missing(df)\n\n# Access statistics\nprintln(\"Total missing: \", results[:stats][:total_missing])\nprintln(\"Overall percentage: \", results[:stats][:overall_percentage], \"%\")\n\n# Access per-column statistics\nfor (col, stats) in results[:stats][:columns]\n    println(\"$col: $(stats[:percentage])% missing\")\nend","category":"section"},{"location":"guide/#Batch-Reporting","page":"User Guide","title":"Batch Reporting","text":"# Generate standalone HTML report\nresults = diagnose_missing(df, report=true, output=\"analysis.html\")\n\nprintln(\"Report saved to: \", results[:report_path])\n# → Report saved to: /absolute/path/to/analysis.html\n\n","category":"section"},{"location":"guide/#Exporting-Plots","page":"User Guide","title":"Exporting Plots","text":"All plotting functions return Makie.Figure objects. Export them using CairoMakie.save().\n\nusing CairoMakie\n\n# Generate a plot\nfig = plot_missing_matrix(df)\n\n# PNG (default 300 DPI)\nsave(\"output.png\", fig)\n\n# PDF (vector format, high quality)\nsave(\"output.pdf\", fig)\n\n# SVG (vector format, editable)\nsave(\"output.svg\", fig)\n\n# High-resolution PNG for publications\nsave(\"high_res.png\", fig, px_per_unit=3)  # 900 DPI equivalent\n\n","category":"section"},{"location":"guide/#Troubleshooting","page":"User Guide","title":"Troubleshooting","text":"","category":"section"},{"location":"guide/#Plots-not-displaying-in-REPL","page":"User Guide","title":"Plots not displaying in REPL","text":"Solution: Activate the CairoMakie backend explicitly\n\nusing CairoMakie\nCairoMakie.activate!()\n\nresults = diagnose_missing(df)","category":"section"},{"location":"guide/#\"Directory-does-not-exist\"-error","page":"User Guide","title":"\"Directory does not exist\" error","text":"Solution: Create the output directory before generating reports\n\noutput_dir = \"reports\"\n!isdir(output_dir) && mkdir(output_dir)\n\nresults = diagnose_missing(df, report=true, output=\"reports/analysis.html\")","category":"section"},{"location":"guide/#Out-of-memory-with-large-datasets","page":"User Guide","title":"Out of memory with large datasets","text":"Solution: Use display=false to skip plot rendering\n\n# For very large datasets (>100K rows)\nresults = diagnose_missing(df, display=false)\n\n# Access statistics only\nprintln(results[:stats])\n\n","category":"section"},{"location":"guide/#Performance-Tips","page":"User Guide","title":"Performance Tips","text":"","category":"section"},{"location":"guide/#For-Large-Datasets-(10K-rows)","page":"User Guide","title":"For Large Datasets (>10K rows)","text":"# Skip interactive display\nresults = diagnose_missing(df, display=false)\n\n# Generate report directly\nresults = diagnose_missing(df, \"report.html\", verbose=true)\n\n","category":"section"},{"location":"guide/#Complete-Reference","page":"User Guide","title":"Complete Reference","text":"For the full user guide with all examples, workflows, and advanced usage, see:\n\nUSER_GUIDE.md","category":"section"},{"location":"api/#API-Reference","page":"API Reference","title":"API Reference","text":"This page provides detailed documentation for all public functions in MissingDataViz.jl.\n\n","category":"section"},{"location":"api/#Pattern-Detection","page":"API Reference","title":"Pattern Detection","text":"Functions for detecting and analyzing missing data patterns.\n\n","category":"section"},{"location":"api/#Visualizations","page":"API Reference","title":"Visualizations","text":"","category":"section"},{"location":"api/#Matrix-Heatmap","page":"API Reference","title":"Matrix Heatmap","text":"","category":"section"},{"location":"api/#Bar-Charts","page":"API Reference","title":"Bar Charts","text":"","category":"section"},{"location":"api/#Correlation-Matrix","page":"API Reference","title":"Correlation Matrix","text":"","category":"section"},{"location":"api/#Overview-Dashboard","page":"API Reference","title":"Overview Dashboard","text":"","category":"section"},{"location":"api/#Reports-and-Workflows","page":"API Reference","title":"Reports and Workflows","text":"Functions for generating reports and complete workflows.\n\n","category":"section"},{"location":"api/#Data-Structures","page":"API Reference","title":"Data Structures","text":"","category":"section"},{"location":"api/#Utility-Functions","page":"API Reference","title":"Utility Functions","text":"","category":"section"},{"location":"api/#Index","page":"API Reference","title":"Index","text":"","category":"section"},{"location":"api/#MissingDataViz.missing_pattern","page":"API Reference","title":"MissingDataViz.missing_pattern","text":"missing_pattern(df::DataFrame) → BitMatrix\n\nConverts a DataFrame to a binary matrix (true = missing, false = present).\n\nArguments\n\ndf::DataFrame: DataFrame to analyze\n\nReturns\n\nBitMatrix: Binary matrix with same dimensions as df (true = missing, false = present)\n\nThrows\n\nArgumentError: If df is empty\n\nExamples\n\ndf = DataFrame(A=[1, missing, 3], B=[4, 5, missing])\npattern = missing_pattern(df)\n# 3×2 BitMatrix:\n#  0  0\n#  1  0\n#  0  1\n\n\n\n\n\n","category":"function"},{"location":"api/#MissingDataViz.missing_count","page":"API Reference","title":"MissingDataViz.missing_count","text":"missing_count(df::DataFrame) → Vector{Int}\n\nCounts the absolute number of missing values per column.\n\nArguments\n\ndf::DataFrame: DataFrame to analyze\n\nReturns\n\nVector{Int}: Number of missing values for each column\n\nThrows\n\nArgumentError: If df is empty\n\nExamples\n\ndf = DataFrame(A=[1, missing, 3], B=[missing, missing, 6])\ncounts = missing_count(df)  # [1, 2]\n\n\n\n\n\n","category":"function"},{"location":"api/#MissingDataViz.missing_percentage","page":"API Reference","title":"MissingDataViz.missing_percentage","text":"missing_percentage(df::DataFrame) → Vector{Float64}\n\nCalculates the percentage of missing values per column.\n\nArguments\n\ndf::DataFrame: DataFrame to analyze\n\nReturns\n\nVector{Float64}: Percentages (0.0 to 100.0) for each column\n\nThrows\n\nArgumentError: If df is empty\n\nExamples\n\ndf = DataFrame(A=[1, missing, 3], B=[4, 5, 6])\npct = missing_percentage(df)  # [33.33, 0.0]\n\n\n\n\n\n","category":"function"},{"location":"api/#MissingDataViz.pattern_counts","page":"API Reference","title":"MissingDataViz.pattern_counts","text":"pattern_counts(df::DataFrame) → Dict{Vector{Bool}, Int}\n\nIdentifies unique missing data patterns and counts their occurrences.\n\nArguments\n\ndf::DataFrame: DataFrame to analyze\n\nReturns\n\nDict{Vector{Bool}, Int}: Dictionary mapping each unique pattern to its count\n\nThrows\n\nArgumentError: If df is empty\n\nExamples\n\ndf = DataFrame(A=[1, missing, 3, missing], B=[missing, 2, missing, 2])\ncounts = pattern_counts(df)\n# Dict with patterns as keys, counts as values\n\n\n\n\n\n","category":"function"},{"location":"api/#MissingDataViz.pattern_frequency","page":"API Reference","title":"MissingDataViz.pattern_frequency","text":"pattern_frequency(df::DataFrame) → Vector{Tuple{Vector{Bool}, Int}}\n\nReturns unique patterns sorted by frequency (most common first).\n\nArguments\n\ndf::DataFrame: DataFrame to analyze\n\nReturns\n\nVector{Tuple{Vector{Bool}, Int}}: Vector of (pattern, count) tuples sorted by count descending\n\nThrows\n\nArgumentError: If df is empty\n\nExamples\n\ndf = DataFrame(A=[1, missing, 3], B=[missing, 2, missing])\nfreq = pattern_frequency(df)\n# [(pattern1, count1), (pattern2, count2), ...] sorted by count\n\n\n\n\n\n","category":"function"},{"location":"api/#MissingDataViz.row_missing_stats","page":"API Reference","title":"MissingDataViz.row_missing_stats","text":"row_missing_stats(df::DataFrame) → Vector{Float64}\n\nCalculates the percentage of missing values for each row.\n\nArguments\n\ndf::DataFrame: DataFrame to analyze\n\nReturns\n\nVector{Float64}: Percentage of missing values per row (0.0 to 100.0)\n\nThrows\n\nArgumentError: If df is empty\n\nExamples\n\ndf = DataFrame(A=[1, missing, 3], B=[missing, 2, missing])\nrow_stats = row_missing_stats(df)\n# [50.0, 50.0, 50.0]  (each row has 1 out of 2 missing)\n\n\n\n\n\n","category":"function"},{"location":"api/#MissingDataViz.column_missing_distribution","page":"API Reference","title":"MissingDataViz.column_missing_distribution","text":"column_missing_distribution(df::DataFrame) → DataFrame\n\nCreates a detailed distribution table of missing values by column.\n\nArguments\n\ndf::DataFrame: DataFrame to analyze\n\nReturns\n\nDataFrame: Table with columns column_name, n_missing, pct_missing, n_present\n\nThrows\n\nArgumentError: If df is empty\n\nExamples\n\ndf = DataFrame(A=[1, missing, 3], B=[4, 5, 6])\ndist = column_missing_distribution(df)\n# 2×4 DataFrame with distribution stats\n\n\n\n\n\n","category":"function"},{"location":"api/#MissingDataViz.extreme_patterns","page":"API Reference","title":"MissingDataViz.extreme_patterns","text":"extreme_patterns(df::DataFrame) → NamedTuple\n\nIdentifies extreme cases: rows/columns that are 100% missing or 100% complete.\n\nArguments\n\ndf::DataFrame: DataFrame to analyze\n\nReturns\n\nNamedTuple with fields:\nrows_all_missing::Vector{Int}: Row indices where all values are missing\nrows_all_complete::Vector{Int}: Row indices where no values are missing\ncols_all_missing::Vector{Int}: Column indices where all values are missing\ncols_all_complete::Vector{Int}: Column indices where no values are missing\n\nThrows\n\nArgumentError: If df is empty\n\nExamples\n\ndf = DataFrame(A=[missing, 1], B=[missing, missing])\nextremes = extreme_patterns(df)\n# extremes.rows_all_missing == [1]\n# extremes.cols_all_missing == [2]\n\n\n\n\n\n","category":"function"},{"location":"api/#MissingDataViz.summarize_missing","page":"API Reference","title":"MissingDataViz.summarize_missing","text":"summarize_missing(df::DataFrame) → NamedTuple\n\nGenerates a comprehensive summary of missing data patterns and statistics.\n\nArguments\n\ndf::DataFrame: DataFrame to analyze\n\nReturns\n\nNamedTuple containing:\ntotal_cells::Int: Total number of cells in DataFrame\nn_missing::Int: Total number of missing values\npct_missing::Float64: Overall percentage of missing values\nby_column::DataFrame: Distribution statistics by column\nby_row::Vector{Float64}: Percentage missing per row\nextremes::NamedTuple: Extreme patterns (all missing/complete rows/cols)\ntop_patterns::Vector: Top 5 most frequent patterns\n\nThrows\n\nArgumentError: If df is empty\n\nExamples\n\ndf = DataFrame(A=[1, missing, 3], B=[4, 5, missing])\nsummary = summarize_missing(df)\nprintln(\"Total missing: \", summary.n_missing)\nprintln(\"By column: \", summary.by_column)\n\n\n\n\n\n","category":"function"},{"location":"api/#MissingDataViz.missing_correlation","page":"API Reference","title":"MissingDataViz.missing_correlation","text":"missing_correlation(df::DataFrame)\n\nCalculate the Pearson correlation matrix between missing data patterns across columns.\n\nThis function converts the DataFrame to a binary matrix (1 = missing, 0 = present) and computes pairwise correlations between columns. Positive correlations indicate columns that tend to have missing values together, while negative correlations suggest opposite patterns.\n\nArguments\n\ndf::DataFrame: Input DataFrame to analyze\n\nReturns\n\nMatrix{Float64}: Correlation matrix (ncols × ncols) where each entry (i,j)  represents the correlation between missingness patterns of columns i and j\n\nExamples\n\nusing DataFrames, MissingDataViz\n\ndf = DataFrame(\n    A = [1, missing, 3, missing, 5],\n    B = [missing, 2, 3, missing, 5],      # Correlates with A\n    C = [1, 2, missing, 4, missing]       # Different pattern\n)\n\ncorr_matrix = missing_correlation(df)\n# corr_matrix[1,2] will be high (A and B missing together)\n\nNotes\n\nReturns NaN for columns with no missing values (constant pattern, no variance)\nDiagonal elements are always 1.0 (perfect self-correlation)\nCorrelation ranges from -1.0 (opposite patterns) to 1.0 (identical patterns)\n\n\n\n\n\n","category":"function"},{"location":"api/#MissingDataViz.plot_missing_matrix","page":"API Reference","title":"MissingDataViz.plot_missing_matrix","text":"plot_missing_matrix(df::DataFrame; kwargs...)\n\nCreate a heatmap visualizing missing data patterns in a DataFrame with customization options.\n\nArguments\n\ndf::DataFrame: DataFrame to visualize\n\nKeyword Arguments\n\nfigsize::Tuple{Int,Int}: Figure dimensions in pixels. Default: (1000, 600)\ncolormap::Symbol: Color scheme for the heatmap. Default: :grays\nshow_sparkline::Bool: Display sparkline showing % missing per row. Default: true\nmax_rows_display::Int: Maximum number of rows to display. Use -1 for no limit. Default: 5000\nlabels::NamedTuple: Custom labels for plot elements. Default labels in English.\nxlabel: X-axis label (default: \"Variables\")\nylabel: Y-axis label (default: \"Observations\")\ntitle: Plot title (default: \"Missing Data Pattern\")\ncolorbar_label: Colorbar label (default: \"Data Status\")\ncolorbar_present: Label for present values (default: \"Present\")\ncolorbar_missing: Label for missing values (default: \"Missing\")\nsparkline_ylabel: Sparkline Y-axis label (default: \"% Missing\")\n\nReturns\n\nFigure: Makie Figure object containing the heatmap\n\nExamples\n\nusing MissingDataViz\nusing DataFrames\n\ndf = DataFrame(\n    A = [1, missing, 3, 4, missing],\n    B = [missing, 2, 3, missing, 5],\n    C = [1, 2, 3, 4, 5]\n)\n\n# Basic usage\nfig = plot_missing_matrix(df)\n\n# French labels\nfig = plot_missing_matrix(df; labels=(\n    xlabel = \"Variables\",\n    ylabel = \"Observations\",\n    title = \"Motif de Données Manquantes\",\n    colorbar_label = \"Statut\",\n    colorbar_present = \"Présent\",\n    colorbar_missing = \"Manquant\",\n    sparkline_ylabel = \"% Manquant\"\n))\n\n# Medical context\nfig = plot_missing_matrix(df; labels=(\n    xlabel = \"Clinical Variables\",\n    ylabel = \"Patients\",\n    title = \"Missing Data in Patient Records\"\n))\n\n# Custom size without sparkline\nfig = plot_missing_matrix(df; figsize=(800, 600), show_sparkline=false)\n\n# Colorblind-friendly colormap\nfig = plot_missing_matrix(df; colormap=:viridis)\n\n# Display more rows\nfig = plot_missing_matrix(df; max_rows_display=10000)\n\n# Combined customization\nfig = plot_missing_matrix(df; \n    figsize=(1200, 800), \n    colormap=:thermal,\n    show_sparkline=true,\n    max_rows_display=3000,\n    labels=(xlabel=\"Features\", ylabel=\"Samples\")\n)\n\nNotes\n\nBlack = missing value (with default :grays colormap)\nWhite = present value (with default :grays colormap)\nFor datasets >50 columns, only the first 50 columns are displayed\nAvailable colormaps: :grays, :viridis, :plasma, :thermal, :RdBu, etc.\nPartial label override is supported (only specify labels you want to change)\n\n\n\n\n\n","category":"function"},{"location":"api/#MissingDataViz.plot_missing_overview","page":"API Reference","title":"MissingDataViz.plot_missing_overview","text":"plot_missing_overview(df::DataFrame; \n                      figsize::Tuple{Int,Int}=(1800, 600),\n                      layout::Symbol=:horizontal,\n                      threshold::Union{Nothing,Float64}=nothing,\n                      show_correlation_values::Union{Bool,Symbol}=:auto)\n\nCreate a comprehensive overview dashboard combining all three missing data visualizations.\n\nCombines:\n\nMissing data matrix (left/top): Shows where missing values occur row-by-row\nBar chart (center): Shows percentage of missing values per column\nCorrelation matrix (right/bottom): Shows relationships between missing patterns\n\nArguments\n\ndf::DataFrame: Input DataFrame to analyze\nfigsize::Tuple{Int,Int}=(1800, 600): Figure dimensions (width, height)\nlayout::Symbol=:horizontal: Layout (:horizontal = 1×3 grid, :vertical = 3×1 grid)\nthreshold::Union{Nothing,Float64}=nothing: Optional threshold line for bar chart\nshow_correlation_values::Union{Bool,Symbol}=:auto: Show values in correlation heatmap\n\nReturns\n\nFigure: Makie Figure containing all three plots in unified layout\n\nExamples\n\nusing DataFrames, MissingDataViz\n\ndf = DataFrame(\n    A = [1, missing, 3, missing, 5],\n    B = [missing, missing, missing, 4, 5],\n    C = [1, 2, 3, 4, 5]\n)\n\n# Default horizontal layout\nfig = plot_missing_overview(df)\n\n# Vertical layout\nfig = plot_missing_overview(df, layout=:vertical, figsize=(1000, 1800))\n\n# With threshold line on bar chart\nfig = plot_missing_overview(df, threshold=30.0)\n\nUse Cases\n\nQuick audit: Complete picture of missing data in single view\nExecutive reports: Comprehensive visual for presentations\nExploratory analysis: Identify patterns, severity, and correlations simultaneously\nBefore imputation: Understand data structure before choosing imputation strategy\n\n\n\n\n\n","category":"function"},{"location":"api/#MissingDataViz.generate_html_report","page":"API Reference","title":"MissingDataViz.generate_html_report","text":"generate_html_report(df::DataFrame, output_file::String; \n                     title::String=\"Missing Data Analysis Report\")\n\nGenerate a comprehensive HTML report with missing data analysis and visualizations.\n\nCreates a standalone HTML file containing:\n\nSummary statistics table (missing count and percentage per column)\nMissing data matrix heatmap\nBar chart of missing percentages\nCorrelation matrix of missingness patterns\nCombined overview dashboard\n\nAll plots are embedded as base64-encoded PNG images, making the report a single  self-contained file with no external dependencies.\n\nArguments\n\ndf::DataFrame: Input data to analyze\noutput_file::String: Path where HTML report will be saved\nRelative paths are resolved from current working directory (pwd())\nAbsolute paths are used as-is\ntitle::String=\"Missing Data Analysis Report\": Report title displayed in header\n\nReturns\n\nString: Absolute path to the generated HTML file\n\nOutput File Path Behavior\n\n# Relative path → saved in current directory\ngenerate_html_report(df, \"report.html\")\n# → Saved at: pwd()/report.html\n\n# Absolute path → saved at specified location\ngenerate_html_report(df, \"/home/user/reports/analysis.html\")\n# → Saved at: /home/user/reports/analysis.html\n\n# Check current directory\npwd()  # See where relative paths will be saved\n\nExamples\n\nusing DataFrames, MissingDataViz\n\n# Create sample data with missing values\ndf = DataFrame(\n    Age = [25, missing, 30, missing, 35],\n    Income = [50000, 60000, missing, 70000, missing],\n    Score = [85, 90, missing, missing, 95]\n)\n\n# Generate report with default title\npath = generate_html_report(df, \"missing_analysis.html\")\nprintln(\"Report saved to: $path\")\n\n# Generate report with custom title\npath = generate_html_report(\n    df, \n    \"custom_report.html\",\n    title=\"Q4 2024 Data Quality Report\"\n)\n\n# Open in browser (cross-platform)\nif Sys.iswindows()\n    run(`cmd /c start $path`)\nelseif Sys.isapple()\n    run(`open $path`)\nelse\n    run(`xdg-open $path`)\nend\n\nPerformance\n\nTypical execution time: 150-300ms for datasets with <10,000 rows\nReport file size: ~500KB - 2MB depending on data size\nMemory usage: ~50MB peak (temporary plot rendering)\n\nNote\n\nThis function generates all visualizations automatically. Plots are always d and embedded as base64 PNG images for maximum portability.\n\nSee Also\n\ndiagnose_missing: All-in-one analysis workflow\nCairoMakie.save(): For exporting individual plots to PNG/PDF/SVG\n\nThrows\n\nErrorException: If output directory doesn't exist or is not writable\nArgumentError: If DataFrame is empty or has no columns\n\n\n\n\n\n","category":"function"},{"location":"api/#MissingDataViz.diagnose_missing","page":"API Reference","title":"MissingDataViz.diagnose_missing","text":"diagnose_missing(df::DataFrame; \n                 report::Bool=false,\n                 output::String=\"missing_report.html\",\n                 display::Bool=!report,\n                 verbose::Bool=false)\n\nPerform comprehensive missing data analysis with automatic visualization and reporting.\n\nThis is the main entry point for missing data diagnosis. It provides two modes:\n\nInteractive mode (report=false): Display plots and return statistics\nBatch mode (report=true): Generate HTML report silently\n\nArguments\n\ndf::DataFrame: Input data to analyze\nreport::Bool=false: Generate HTML report (batch mode)\nfalse (default): Interactive mode - display plots in current environment\ntrue: Batch mode - generate HTML file silently\noutput::String=\"missing_report.html\": Output path for HTML report\nOnly used when report=true\nRelative paths resolved from pwd()\nAbsolute paths used as-is\ndisplay::Bool=!report: Display plots interactively\nIgnored if report=true (batch mode implies no interactive display)\nOnly effective in interactive mode (report=false)\nverbose::Bool=false: Enable detailed logging\nfalse (default): Minimal output - only final result message\ntrue: Detailed logging of each step\n\nReturns\n\nDict with the following structure:\nDict(\n    :stats => Dict(\n        :total_missing => Int,\n        :total_cells => Int,\n        :overall_percentage => Float64,\n        :columns => Dict(\"col\" => Dict(:count, :percentage))\n    ),\n    :figures => Dict(\n        :matrix => Figure,\n        :bars => Figure,\n        :correlation => Figure,\n        :overview => Figure\n    ),\n    :report_path => String  # Only present if report=true\n)\n\nBehavior\n\nInteractive Mode (report=false)\n\n# Display plots and return statistics\nresults = diagnose_missing(df)\n\n# Access statistics\nprintln(\"Total missing: \", results[:stats][:total_missing])\n\n# Access figures for further manipulation\nmatrix_fig = results[:figures][:matrix]\nsave(\"custom_matrix.png\", matrix_fig)  # Export with CairoMakie\n\n# Suppress display (compute only)\nresults = diagnose_missing(df, display=false)\n\nBatch Mode (report=true)\n\n# Generate HTML report silently\nresults = diagnose_missing(df, report=true)\nprintln(\"Report: \", results[:report_path])\n\n# Custom output path\nresults = diagnose_missing(df, report=true, output=\"analysis/report.html\")\n\n# Verbose logging\nresults = diagnose_missing(df, report=true, verbose=true)\n# → \"Computing missing data statistics...\"\n# → \"Generating visualizations...\"\n# → \"Generating HTML report...\"\n# → \"Report generated: /path/to/report.html\"\n\nExamples\n\nusing DataFrames, MissingDataViz\n\n# Create sample data\ndf = DataFrame(\n    Name = [\"Alice\", \"Bob\", missing, \"David\", \"Eve\"],\n    Age = [25, missing, 30, missing, 35],\n    Salary = [50000, 60000, missing, 70000, missing],\n    Department = [\"HR\", \"IT\", \"IT\", missing, \"HR\"]\n)\n\n# Example 1: Quick interactive analysis\nresults = diagnose_missing(df)\n# → Displays 4 plots automatically\n# → Returns statistics and figures\n\n# Example 2: Generate report for sharing\nresults = diagnose_missing(df, report=true, output=\"team_review.html\")\n# → Creates team_review.html\n# → Silent execution (no plots displayed)\n\n# Example 3: Debug mode with verbose logging\nresults = diagnose_missing(df, report=true, verbose=true)\n# → Shows detailed progress of each step\n\n# Example 4: Compute stats without displaying plots\nresults = diagnose_missing(df, display=false)\n# → No visual output, only statistics computed\n\n# Example 5: Access specific statistics\nresults = diagnose_missing(df)\nfor (col, stats) in results[:stats][:columns]\n    if stats[:percentage] > 20\n        println(\"$col has $(stats[:percentage])% missing - investigate!\")\n    end\nend\n\nPerformance\n\nInteractive mode: 150-250ms (display time depends on backend)\nBatch mode: 200-350ms (includes HTML generation and file write)\nMemory: ~50-100MB peak (temporary plot rendering)\n\nNotes\n\nThe display parameter is ignored when report=true to avoid confusion\nIn batch mode, plots are never displayed interactively\nAll plots are always generated (for both modes)\nUse verbose=true for debugging or progress monitoring\n\nSee Also\n\ngenerate_html_report: Generate HTML report only (no interactive display)\nplot_missing_overview: Generate combined overview plot only\nCairoMakie.save(): Export individual plots to files\n\nThrows\n\nArgumentError: If DataFrame is empty or has no columns\nErrorException: If report output directory doesn't exist (batch mode only)\n\n\n\n\n\ndiagnose_missing(df::DataFrame, output_file::String; kwargs...)\n\nConvenience method: Generate report by default when output file is specified.\n\nThis is a shorthand for diagnose_missing(df; report=true, output=output_file, kwargs...).\n\nExamples\n\n# These two calls are equivalent:\ndiagnose_missing(df, \"report.html\")\ndiagnose_missing(df, report=true, output=\"report.html\")\n\n\n\n\n\n","category":"function"},{"location":"api/#MissingDataViz.PatternInfo","page":"API Reference","title":"MissingDataViz.PatternInfo","text":"PatternInfo\n\nStructure to store information about a specific missing data pattern.\n\nFields\n\npattern::Vector{Bool}: The binary pattern (true = missing, false = present)\ncount::Int: Number of rows with this pattern\nfrequency::Float64: Percentage of rows with this pattern (0.0 to 100.0)\nrow_indices::Vector{Int}: Indices of rows that have this pattern\n\nExamples\n\ninfo = PatternInfo(\n    pattern = [true, false, true],\n    count = 5,\n    frequency = 25.0,\n    row_indices = [2, 7, 10, 15, 18]\n)\n\n\n\n\n\n","category":"type"},{"location":"api/#MissingDataViz.validate_dataframe","page":"API Reference","title":"MissingDataViz.validate_dataframe","text":"validate_dataframe(df)\n\nValidates that a DataFrame is appropriate for analysis. Throws an error if the DataFrame is empty or invalid.\n\nArguments\n\ndf: Object to validate (must be a DataFrame)\n\nThrows\n\nArgumentError: If df is not a DataFrame\nArgumentError: If df is empty (0 rows or 0 columns)\n\nExamples\n\ndf = DataFrame(A=[1,2,3])\nvalidate_dataframe(df)  # Passes without error\n\ndf_empty = DataFrame()\nvalidate_dataframe(df_empty)  # Throws ArgumentError\n\n\n\n\n\n","category":"function"},{"location":"#MissingDataViz.jl","page":"Home","title":"MissingDataViz.jl","text":"Professional missing data visualization and diagnosis for Julia DataFrames\n\n","category":"section"},{"location":"#Overview","page":"Home","title":"Overview","text":"MissingDataViz.jl provides comprehensive tools for analyzing and visualizing missing data patterns in tabular datasets. It combines intuitive visualizations with robust pattern detection to help you understand the structure of missingness in your data.\n\nKey Features:\n\n🔍 Pattern Detection: Identify unique missing data patterns and their frequencies\n📊 Multiple Visualizations: Matrix heatmaps, bar charts, correlation matrices, overview dashboards\n📄 HTML Reports: Generate standalone reports with embedded visualizations\n💾 Export Flexibility: Save plots as PNG, PDF, or SVG\n⚡ One-Line Diagnosis: Complete analysis with diagnose_missing()\n\n","category":"section"},{"location":"#Installation","page":"Home","title":"Installation","text":"using Pkg\nPkg.add(\"MissingDataViz\")\n\nDevelopment version:\n\nusing Pkg\nPkg.add(url=\"https://github.com/DescarteS96/MissingDataViz.jl\")\n\n","category":"section"},{"location":"#Quick-Start","page":"Home","title":"Quick Start","text":"using MissingDataViz\nusing DataFrames\n\n# Create sample data with missing values\ndf = DataFrame(\n    Name = [\"Alice\", \"Bob\", missing, \"David\", \"Eve\"],\n    Age = [25, missing, 30, missing, 35],\n    Salary = [50000, 60000, missing, 70000, missing],\n    Department = [\"HR\", \"IT\", \"IT\", missing, \"HR\"]\n)\n\n# One-line complete analysis\nresults = diagnose_missing(df)\n# → Displays 4 plots automatically\n# → Returns statistics and figures\n\n# Generate HTML report for sharing\ndiagnose_missing(df, report=true, output=\"analysis.html\")\n# → Creates standalone HTML file\n\n","category":"section"},{"location":"#Visualizations","page":"Home","title":"Visualizations","text":"","category":"section"},{"location":"#Missing-Data-Matrix","page":"Home","title":"Missing Data Matrix","text":"fig = plot_missing_matrix(df)\n\nShows: Binary heatmap of missing values (black = missing, white = present) with optional sparkline showing % missing per row.","category":"section"},{"location":"#Bar-Chart","page":"Home","title":"Bar Chart","text":"fig = plot_missing_bars(df)\n\nShows: Percentage of missing values per column, color-coded by severity (blue < 20%, orange 20-50%, red ≥ 50%).","category":"section"},{"location":"#Correlation-Matrix","page":"Home","title":"Correlation Matrix","text":"fig = plot_missing_correlation(df)\n\nShows: Correlation between missing data patterns across columns to detect co-occurrence.","category":"section"},{"location":"#Overview-Dashboard","page":"Home","title":"Overview Dashboard","text":"fig = plot_missing_overview(df)\n\nShows: Combined view of all three plots above in a single figure.\n\n","category":"section"},{"location":"#Workflows","page":"Home","title":"Workflows","text":"","category":"section"},{"location":"#Interactive-Analysis","page":"Home","title":"Interactive Analysis","text":"# Display plots and access statistics\nresults = diagnose_missing(df)\n\n# Access statistics\nprintln(\"Total missing: \", results[:stats][:total_missing])\nprintln(\"Overall %: \", results[:stats][:overall_percentage])\n\n# Save individual plots\nusing CairoMakie\nsave(\"matrix.png\", results[:figures][:matrix])\nsave(\"overview.pdf\", results[:figures][:overview])","category":"section"},{"location":"#Batch-Reporting","page":"Home","title":"Batch Reporting","text":"# Generate HTML report (no interactive display)\nresults = diagnose_missing(df, report=true, output=\"report.html\")\n\n# Open in browser\npath = results[:report_path]\n# Windows: run(`cmd /c start $path`)\n# macOS: run(`open $path`)\n# Linux: run(`xdg-open $path`)\n\n","category":"section"},{"location":"#Navigation","page":"Home","title":"Navigation","text":"Pages = [\"api.md\", \"guide.md\"]\nDepth = 2\n\nAPI Reference: Complete function documentation\nUser Guide: Detailed workflows, troubleshooting, and examples\n\n","category":"section"},{"location":"#Performance","page":"Home","title":"Performance","text":"Interactive mode: 150-250ms for typical datasets (1000 rows × 10 columns)\nBatch mode: 200-350ms (includes HTML generation)\nMaximum recommended size: 100k rows × 100 columns\n\n","category":"section"},{"location":"#Support","page":"Home","title":"Support","text":"GitHub: github.com/DescarteS96/MissingDataViz.jl\nIssues: Report bugs or request features\nDocumentation: Online docs\n\n","category":"section"},{"location":"#Citation","page":"Home","title":"Citation","text":"If you use MissingDataViz.jl in your research, please cite:\n\n@software{missingdataviz2025,\n  author = {Ballamou, Rene Fassou},\n  title = {MissingDataViz.jl: Missing Data Visualization for Julia},\n  year = {2025},\n  url = {https://github.com/DescarteS96/MissingDataViz.jl}\n}\n\n","category":"section"},{"location":"#Index","page":"Home","title":"Index","text":"","category":"section"}]
}
